<div class="container admin-main"><div class="admin-title-row"><div><h1>پلن‌های همکاری</h1><p>قیمت‌ها از بخش تعرفه مدیریت می‌شوند؛ انتشار هر پلن مستقل از مبلغ است.</p></div><a class="btn btn-outline" href="<?= e(site_url('/pricing')) ?>" target="_blank" rel="noopener">مشاهده صفحه تعرفه‌ها</a></div>
<div class="admin-panel"><h2>افزودن پلن</h2><form class="admin-form" action="<?= e(site_url('/admin/plans/save')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="0"><div class="field"><label>عنوان پلن</label><input name="title" required maxlength="150" placeholder="مثلاً حرفه‌ای"></div><div class="field"><label>شناسه لاتین URL</label><input name="slug" required dir="ltr" pattern="[a-z0-9-]+" placeholder="professional"></div><div class="field"><label>مناسب برای</label><input name="audience" required maxlength="250"></div><div class="field"><label>مرتبط با خدمت (اختیاری)</label><select name="service_id"><option value="0">پلن عمومی</option><?php foreach ($services as $service): ?><option value="<?= (int) $service['id'] ?>"><?= e($service['title']) ?></option><?php endforeach; ?></select></div><div class="field full"><label>معرفی</label><textarea name="summary" maxlength="600" required></textarea></div><div class="field full"><label>امکانات (هر مورد در یک خط)</label><textarea name="features" maxlength="6000"></textarea></div><div class="field"><label>ترتیب نمایش</label><input name="display_order" type="number" min="0" max="999" value="0"></div><div class="field checkbox"><input id="new-featured" type="checkbox" name="is_featured"><label for="new-featured">نمایش به‌عنوان پلن پیشنهادی</label></div><div class="field checkbox"><input id="new-published" type="checkbox" name="is_published" checked><label for="new-published">انتشار عمومی</label></div><div class="form-actions"><button class="btn btn-dark" type="submit">افزودن پلن</button></div></form></div>
<div class="admin-panel"><h2>پلن‌های ثبت‌شده</h2><?php if ($plans === []): ?><div class="empty-state">پلنی ثبت نشده است.</div><?php else: ?><div class="edit-list"><?php foreach ($plans as $plan): ?><details class="edit-drawer"><summary><span><strong><?= e($plan['title']) ?></strong><small><?= e($plan['audience']) ?> · <?= $plan['is_published'] ? 'منتشرشده' : 'پیش‌نویس' ?></small></span><span class="status-badge <?= $plan['is_published']?'status-won':'status-lost' ?>"><?= $plan['is_published']?'عمومی':'پیش‌نویس' ?></span></summary><form class="admin-form edit-form" action="<?= e(site_url('/admin/plans/save')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$plan['id'] ?>"><div class="field"><label>عنوان</label><input name="title" required maxlength="150" value="<?= e($plan['title']) ?>"></div><div class="field"><label>شناسه لاتین</label><input name="slug" required dir="ltr" value="<?= e($plan['slug']) ?>"></div><div class="field"><label>مناسب برای</label><input name="audience" required maxlength="250" value="<?= e($plan['audience']) ?>"></div><div class="field"><label>خدمت مرتبط</label><select name="service_id"><option value="0">پلن عمومی</option><?php foreach ($services as $service): ?><option value="<?= (int)$service['id'] ?>" <?= (int)$plan['service_id']===(int)$service['id']?'selected':'' ?>><?= e($service['title']) ?></option><?php endforeach; ?></select></div><div class="field full"><label>معرفی</label><textarea name="summary" required maxlength="600"><?= e($plan['summary']) ?></textarea></div><div class="field full"><label>امکانات، هر مورد در یک خط</label><textarea name="features"><?= e($plan['features_text']) ?></textarea></div><div class="field"><label>ترتیب نمایش</label><input name="display_order" type="number" min="0" max="999" value="<?= (int)$plan['display_order'] ?>"></div><div class="field checkbox"><input id="featured-<?= (int)$plan['id'] ?>" type="checkbox" name="is_featured" <?= $plan['is_featured']?'checked':'' ?>><label for="featured-<?= (int)$plan['id'] ?>">پلن پیشنهادی</label></div><div class="field checkbox"><input id="published-<?= (int)$plan['id'] ?>" type="checkbox" name="is_published" <?= $plan['is_published']?'checked':'' ?>><label for="published-<?= (int)$plan['id'] ?>">انتشار عمومی</label></div><div class="form-actions"><button class="btn btn-dark" type="submit">ذخیره پلن</button><a class="btn btn-outline" href="<?= e(site_url('/admin/prices')) ?>">مدیریت قیمت</a></div></form></details><?php endforeach; ?></div><?php endif; ?></div></div>
